import { mapBackProductToFront } from '@apps/Products/@mappers/products.mapper';

import {
  IFullRecipeDTO,
  IRecipeDTO,
  IRecipeProductDTO,
  IRecipesCategoryDTO,
  IRecipesGroupsDTO,
  IRecipeStructureProductDTO,
  IRecipeUsagesDTO,
} from '../@types/recipes.backTypes';
import {
  IFullRecipe,
  IRecipeProduct,
  IRecipe,
  IRecipeCategory,
  IRecipesGroup,
  IRecipeStructureProduct,
  IRecipeUsage,
} from '../@types/recipes.types';

export const mapRecipeToFront = (backData: IRecipeDTO): IRecipe => {
  return {
    id: +backData.id,
    name: backData.name,
    promo: backData.promo_text,
    photo: backData.photo,
    text: backData?.text ?? '',
    amount: +backData.amount,
    carbs: +backData.carbohydrates,
    protein: +backData.protein,
    fat: +backData.fat,
    energy: +backData.energy,
    id_author: +backData.id_author,
    water_count: backData.water_count ? +backData.water_count : null,
    gas_count: backData.gas_count ? +backData.gas_count : null,
    cooking_time: backData.cooking_time ? +backData.cooking_time : null,
  };
};

export const mapRecipeGroupToFront = (backData: IRecipesGroupsDTO): IRecipesGroup => {
  return {
    id: +backData.id,
    name: backData.name,
    items: backData.items.map(mapRecipeToFront),
  };
};

const mapBackRecipesProductToFront = (backData: IRecipeProductDTO): IRecipeProduct => {
  return {
    ...mapBackProductToFront(backData),
    amount: +backData.amount,
    id_product: +backData.id_product,
  };
};

export const mapFullRecipeToFront = (backData: IFullRecipeDTO): IFullRecipe => {
  return {
    id: +backData.id,
    name: backData.name,
    promo: backData.promo_text,
    photo: backData.photo,
    water_count: backData.water_count ? +backData.water_count : null,
    gas_count: backData.gas_count ? +backData.gas_count : null,
    cooking_time: backData.cooking_time ? +backData.cooking_time : null,
    text: backData.text,
    amount: +backData.summ.amount,
    carbs: +backData.summ.carbohydrates,
    protein: +backData.summ.protein,
    fat: +backData.summ.fat,
    energy: +backData.summ.energy,
    id_author: +backData.author_id,
    products: backData.products.map(mapBackRecipesProductToFront),
    author: {
      id: +backData.author_id,
      name: backData.author_name,
      surname: backData.author_surname,
      photo: backData.author_photo,
    },
    category: {
      id: +backData.category_id,
      name: backData.category_name,
    },
  };
};

export const mapRecipeCategoryToFront = (backData: IRecipesCategoryDTO): IRecipeCategory => {
  return {
    id: +backData.id,
    name: backData.name,
  };
};

export const mapRecipeStructureProductsToFront = (
  backData: IRecipeStructureProductDTO,
): IRecipeStructureProduct => {
  return {
    ...mapBackRecipesProductToFront(backData),
    id: +backData.id_product,
    id_recipes_structure: +backData.id,
    kkal: backData.kkal,
  };
};

export const mapRecipeUsagesToFront = (backData: IRecipeUsagesDTO): IRecipeUsage => {
  return {
    byHiking: backData.by_hiking.map((b) => ({
      hiking: {
        id: +b.id,
        name: b.name,
        ava: b.ava,
        start: new Date(b.start),
        finish: new Date(b.finish),
      },
      count: +b.usages,
    })),
    byAct: backData.by_act.map((b) => ({
      act: {
        id: +b.id,
        name: b.name,
      },
      count: +b.usages,
    })),
    byYear: backData.by_year.map((b) => ({
      year: +b.year,
      count: +b.usages,
    })),
  };
};
